// Simple canvas game based on IDEA.md
(function(){
  const canvas=document.getElementById('game');
  if(!canvas){console.error('Canvas #game not found');return;}
  const ctx=canvas.getContext('2d');
  const W=canvas.width=canvas.clientWidth||800;
  const H=canvas.height=canvas.clientHeight||600;

  // ---- Game objects ----
  const ship={x:W/2,y:H/2,angle:0,vx:0,vy:0,r:10};
  const asteroids=[]; // each {x,y,vx,vy,r}
  const orbs=[]; // each {x,y,r,ttl}
  let keys={};
  let score=0, orbScore=0, start=Date.now();
  let gameOver=false;
  let asteroidSpawn=2000; // ms
  let lastAsteroid=Date.now();
  let orbSpawn=5000;
  let lastOrb=Date.now();

input.oldString:
// ship
  ctx.save();
  ctx.translate(ship.x,ship.y);
  ctx.rotate(ship.angle);
  ctx.beginPath();
  ctx.moveTo(12,0);
  ctx.lineTo(-8,6);
  ctx.lineTo(-8,-6);
  ctx.closePath();
  ctx.fillStyle='white';
  ctx.fill();
  ctx.restore();

input.newString:
// ship with optional thrust flame
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  // thrust flame
  if (keys['ArrowUp']) {
    ctx.beginPath();
    ctx.moveTo(-10, 0);
    ctx.lineTo(-20, -5);
    ctx.lineTo(-20, 5);
    ctx.closePath();
    ctx.fillStyle = 'orange';
    ctx.fill();
  }
  // ship body
  ctx.beginPath();
  ctx.moveTo(12, 0);
  ctx.lineTo(-8, 6);
  ctx.lineTo(-8, -6);
  ctx.closePath();
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.restore();

